return [{
  json: {
    campanha_id: 1,       // mesmo id usado em 02-enfileirar
    tamanho_lote_padrao: 100,
  },
}];

const g = items[0].json;
const params = $('Parâmetros').first().json;

const partes = new Intl.DateTimeFormat('en-US', {
  timeZone: 'America/Sao_Paulo', hour: 'numeric', hour12: false, weekday: 'short',
}).formatToParts(new Date());
const hora = parseInt(partes.find((p) => p.type === 'hour').value, 10);
const diaSemana = partes.find((p) => p.type === 'weekday').value; // 'Mon'..'Sun'

const diaUtil = diaSemana !== 'Sun'; // permite sábado — só domingo fica de fora
const dentroDaJanela = diaUtil && hora >= 9 && hora < 18;

const limite = g.limite != null ? parseInt(g.limite, 10) : 0;
const usado = g.usado != null ? parseInt(g.usado, 10) : 0;
const cotaRestante = Math.max(limite - usado, 0);

let bloqueadoMotivo = null;
if (!g.id) bloqueadoMotivo = 'campanha_inexistente';
else if (g.pausada) bloqueadoMotivo = 'campanha_pausada';
else if (!dentroDaJanela) bloqueadoMotivo = 'fora_da_janela';
else if (cotaRestante <= 0) bloqueadoMotivo = 'cota_esgotada';

const tamanhoLote = bloqueadoMotivo ? 0 : Math.min(params.tamanho_lote_padrao, cotaRestante);

return [{
  json: {
    campanha_id: params.campanha_id,
    modo_whitelist: !!g.modo_whitelist,
    assunto_email: g.assunto_email,
    tamanho_lote: tamanhoLote,
    bloqueado_motivo: bloqueadoMotivo,
  },
}];

const crypto = require('crypto');

const campanha = $('Avaliar Guardas').first().json;
const secret = $env.UNSUBSCRIBE_HMAC_SECRET || '';
const webhookBase = ($env.WEBHOOK_URL || '').replace(/\/$/, '');
const fromAddr = $env.SENDGRID_FROM;

const EVENTO_DATA = '1 de setembro às 20h';
const EVENTO_LINK = 'https://www.useady.com.br/workshop';
const MEET_LINK = 'https://meet.google.com/aoi-orjx-ouj';

function tokenDescadastro(userId, email) {
  return crypto.createHmac('sha256', secret).update(`${userId}:${email}`).digest('hex');
}

// Corpo do e-mail por campanha — cada campanha_id tem seu próprio texto.
const PARAGRAFOS_POR_CAMPANHA = {
  // Campanha 1 — Convite original
  1: (nome) => [
    nome ? `Olá ${nome},` : 'Olá,',
    'Aqui é o Jean, membro do BNI DECISION de Joinville, tudo bem?',
    'Eu montei um workshop na qual eu vou revelar uma forma de você atrair mais clientes todo dia '
      + 'para o seu negócio através da internet, com uma ferramenta online na qual você vai investir '
      + 'menos de R$ 500 por mês e que vai substituir uma agência completa, na qual você gastaria '
      + 'talvez mais de R$ 2.000 por mês para ela fazer a mesma coisa.',
    `Esse workshop vai acontecer no dia ${EVENTO_DATA} e será EXCLUSIVO para membros do BNI.`,
    `A inscrição é 100% GRÁTIS e pode ser realizada aqui: ${EVENTO_LINK}`,
    'Posso contar contigo?',
  ],
  // Campanha 3 — Lembrete 2: "Amanhã, mesmo horário" (Seg 31/08 20h)
  3: (nome) => [
    nome ? `Oi ${nome},` : 'Oi,',
    'Amanhã, terça, 20h — exatamente essa hora — começa o workshop "O Instagram que vende sozinho".',
    `O link de acesso é este: ${MEET_LINK}`,
    'Guarda esse email ou salva o link em algum lugar fácil de achar amanhã à noite. São só 60 minutos '
      + 'e não vai ter segunda chance de assistir depois.',
    'Te vejo lá.',
    'Jean Dentz',
  ],
  // Campanha 5 — Lembrete 4: "Começa em 2 horas" (Ter 01/09 18h)
  5: (nome) => [
    nome ? `Oi ${nome},` : 'Oi,',
    'Faltam 2 horas. O workshop "O Instagram que vende sozinho" começa às 20h.',
    `Acesso direto: ${MEET_LINK}`,
    'Entra 5 minutos antes pra já garantir sua conexão. Não vai ter gravação — quem perder, perde mesmo.',
    'Abraço,',
    'Jean Dentz',
  ],
};

const montarParagrafos = PARAGRAFOS_POR_CAMPANHA[campanha.campanha_id];
if (!montarParagrafos) {
  throw new Error(`Campanha de e-mail sem texto cadastrado: campanha_id=${campanha.campanha_id}. Adicione em PARAGRAFOS_POR_CAMPANHA.`);
}

return items.map((it) => {
  const { id, destino, contato_user_id, nome } = it.json;
  const token = tokenDescadastro(contato_user_id, destino);
  const unsubUrl = `${webhookBase}/webhook/descadastro?u=${encodeURIComponent(contato_user_id)}`
    + `&e=${encodeURIComponent(destino)}&t=${token}`;

  const paragrafos = montarParagrafos(nome);
  const html = paragrafos.map((p) => `<p>${p}</p>`).join('\n')
    + `<p><a href="${unsubUrl}">Descadastrar</a></p>`;
  const text = paragrafos.join('\n\n') + `\n\nDescadastrar: ${unsubUrl}`;

  const corpo = {
    personalizations: [
      { to: [{ email: destino }], custom_args: { envio_id: String(id) } },
    ],
    from: { email: fromAddr },
    subject: campanha.assunto_email,
    content: [
      { type: 'text/plain', value: text },
      { type: 'text/html', value: html },
    ],
    headers: {
      'List-Unsubscribe': `<${unsubUrl}>, <mailto:descadastro@envios.seudominio.com.br>`,
      'List-Unsubscribe-Post': 'List-Unsubscribe=One-Click',
    },
  };

  return { json: { ...it.json, corpoJson: JSON.stringify(corpo) } };
});

const claimed = $('Claim Atômico do Lote').all();

function backoffSql() {
  return `UPDATE envios SET
            status = CASE WHEN tentativas >= 5 THEN 'falha' ELSE 'pendente' END,
            erro_tipo = CASE WHEN tentativas >= 5 THEN 'permanente' ELSE 'temporario' END,
            erro_codigo = $2, erro_mensagem = $3,
            agendado_para = CASE tentativas
              WHEN 1 THEN now() + interval '5 minutes'
              WHEN 2 THEN now() + interval '15 minutes'
              WHEN 3 THEN now() + interval '1 hour'
              WHEN 4 THEN now() + interval '4 hours'
              ELSE now() + interval '12 hours'
            END,
            atualizado_em = now()
          WHERE id = $1;`;
}

const out = [];
for (let i = 0; i < items.length; i++) {
  const resp = items[i].json;
  const envio = claimed[i].json;
  const statusCode = resp.statusCode;
  const headers = resp.headers || {};
  const body = resp.body || {};

  let sql;
  let params;
  let sucesso = false;

  if (statusCode >= 200 && statusCode < 300) {
    sucesso = true;
    const messageId = headers['x-message-id'] || null;
    sql = 'UPDATE envios SET status=\'enviado\', provider_message_id=$2, enviado_em=now(), atualizado_em=now() WHERE id=$1;';
    params = [envio.id, messageId];
  } else {
    const errros = (body && body.errors) || [];
    const mensagem = errros.map((e) => e.message).join('; ') || `HTTP ${statusCode}`;
    const pareceEmailInvalido = /does not contain a valid address|invalid.*email/i.test(mensagem);

    if (statusCode === 400 && pareceEmailInvalido) {
      sql = `WITH alvo AS (
               UPDATE envios SET status='falha', erro_tipo='permanente', erro_codigo='400', erro_mensagem=$2, atualizado_em=now()
               WHERE id=$1 RETURNING destino
             )
             INSERT INTO supressao (canal, destino, motivo)
             SELECT 'email', destino, 'invalido' FROM alvo
             ON CONFLICT (canal, destino) DO NOTHING;`;
      params = [envio.id, mensagem.slice(0, 500)];
    } else {
      // Demais erros (401/403/429/5xx/desconhecido): temporário por padrão — mais seguro
      // que suprimir um contato válido por causa de um problema do lado da conta/API.
      sql = backoffSql();
      params = [envio.id, String(statusCode), mensagem.slice(0, 500)];
    }
  }

  out.push({ json: { sql, params, sucesso } });
}
return out;
